const seeded=seed=>()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('toast');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('toast'),3200)}
function sound(kind='pop'){if(!data.settings.sound)return;try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;const ctx=sound.ctx||(sound.ctx=new A());ctx.resume();const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.setValueAtTime(kind==='wrong'?180:kind==='win'?660:460,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(kind==='wrong'?100:900,ctx.currentTime+.12);gain.gain.setValueAtTime(.055,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.17);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.18)}catch{}}
function speak(word){if(!data.settings.sound)return;const synth=window.speechSynthesis;if(!synth){toast('這個瀏覽器不支援單字朗讀。');return}synth.cancel();const u=new SpeechSynthesisUtterance(word);u.lang=data.settings.accent;u.rate=.83;const voices=synth.getVoices();const voice=voices.find(v=>v.lang===u.lang)||voices.find(v=>v.lang.startsWith('en'));if(voice)u.voice=voice;synth.speak(u)}
