function shell(content){$('#board')?.resizeWatcher?.disconnect();$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><button class="brand" data-go="home"><span class="press-seal" aria-hidden="true">W<span>✦</span></span><span>單字奇遇記<small>THE LITTLE WORD PRESS</small></span></button><nav class="nav" aria-label="主要導覽">${navItems.map(([id,icon,name])=>`<button data-go="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span>${icon}</span><span>${name}</span></button>`).join('')}</nav><div class="side-bottom"><div class="side-note"><b>給好奇的你，一頁新故事。</b>把路上的單字，<br>變成自己的故事。<span style="display:block;margin-top:9px">✦ 每日建議練習 15–30 分鐘</span></div><button class="profile" data-go="account" style="background:none;width:100%;text-align:left"><span class="avatar">${character().icon}</span><span><b>${esc(currentUser()?.nickname||'小小探險家')}</b><small>${rank()} · 第 ${themeIndex+1} 章</small></span><span style="margin-left:auto;color:#9da48f">⚙</span></button></div></aside><main class="workspace"><header class="topbar"><div class="crumb"><span>小小英文故事社</span><b>／ ${navItems.find(n=>n[0]===page)?.[2]||({settings:'冒險設定',game:'單字大冒險',ranks:'冒險排行榜'}[page]||'準備出發')}</b></div><div class="resources"><span class="resource"><i>⭐</i>${Object.values(data.stars).reduce((a,b)=>a+b,0)}</span><span class="resource"><i>🪙</i><span id="coins">${data.coins}</span></span><button class="icon" data-action="sound" aria-label="${data.settings.sound?'關閉':'開啟'}聲音" title="聲音">${data.settings.sound?'♫':'♪̸'}</button><button class="account-short" data-go="account">${currentUser()?'🦊 @'+esc(currentUser().username):'登入 / 註冊'}</button><button class="icon" data-go="settings" aria-label="冒險設定">⚙</button><button class="icon" data-action="help" aria-label="遊戲說明">?</button></div></header><div class="content"><div class="page">${content}</div></div></main></div>`;bindCommon()}
function rank(){const finished=Object.keys(data.stars).length;return finished>60?'單字大師':finished>30?'單字達人':finished>8?'單字學徒':'單字新手'}
function heading(eyebrow,title,desc,right=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${right}</div>`}
function bindCommon(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));document.querySelectorAll('[data-action="sound"]').forEach(b=>b.onclick=()=>{data.settings.sound=!data.settings.sound;save();b.textContent=data.settings.sound?'♫':'♪̸';b.setAttribute('aria-label',data.settings.sound?'關閉聲音':'開啟聲音');if(!data.settings.sound)window.speechSynthesis?.cancel()});document.querySelectorAll('[data-action="help"]').forEach(b=>b.onclick=help);document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(b.dataset.speak))}
function navigate(to){if(page==='game'&&game&&!game.ended){if(busy){toast('等方塊落好再離開喔。');return}modal(`<div class="modal-hero">🌿</div><h2>先休息一下嗎？</h2><p>這一關尚未完成，離開會結束這次挑戰。</p><button class="btn" id="stay">繼續冒險</button><button class="btn secondary" id="leave">離開關卡</button>`);$('#stay').onclick=closeModal;$('#leave').onclick=()=>{if(game.online){submitScore(true);leaveSession();}record(false);game.ended=true;closeModal();show(to)};return}show(to)}
function show(to){if(roomSession&&roomSession.room.status==='waiting'&&page==='multi'&&to!=='multi')leaveSession();page=to;selected=-1;if(to!=='multi'&&to!=='game')clearInterval(roomTimer);({home:home,map:map,multi:multi,review:review,report:report,settings:settings,ranks:ranks,account:accountPage}[to]||home)();window.scrollTo({top:0,behavior:'instant'})}
function home(){const level=themeIndex*4+1,t=themes[themeIndex];shell(`<div class="book-kicker"><span>THE LITTLE WORD PRESS</span><i>— 每個單字，都是故事的開始 —</i><span>VOL. 01 · FOR CURIOUS MINDS</span></div><section class="book-hero" aria-label="翻開英語故事書"><div class="book-left"><span class="book-tag">A LITTLE WORD ADVENTURE</span><h1>Words that<br><em>open</em><br>little<br><strong>worlds.</strong></h1><h2>翻開故事，玩懂英文。</h2><p>沿著故事小路，把圖片、英文和中文連成一線。<br>從動物森林出發，走進二十個好奇的世界。</p><span class="book-folio">PAGE <b>001</b></span></div><div class="book-spine" aria-hidden="true"></div><div class="book-right"><span class="book-note">ONCE UPON A WORD</span><span class="book-star star-one" aria-hidden="true">✦</span><span class="book-star star-two" aria-hidden="true">✧</span><figure class="book-illustration"><img src="${pressHare}" alt="戴著紙皇冠與懷錶的水彩兔子，站在薄荷綠葉叢中" width="1792" height="2560" fetchpriority="high"><figcaption>圖版一 · 好奇的領路人</figcaption></figure><span class="book-ribbon ribbon-left">翻開</span><span class="book-ribbon ribbon-right">出發</span><span class="book-word-stamp">rabbit<br><small>兔子</small></span><span class="book-folio">002</span></div></section><div class="book-actions"><div><button class="btn" id="adventure">翻開故事目錄 <span>↗</span></button><button class="btn secondary" id="how-to-play">怎麼玩這本書？</button></div><div class="book-colophon"><span><b>20</b><small>主題章節</small></span><span><b>80</b><small>小小挑戰</small></span><span><b>3</b><small>單字的樣子</small></span></div></div><section class="story-flow" aria-label="遊玩方式"><div class="flow-step"><b>01</b><span>挑一個故事<small>在目錄選擇喜歡的主題</small></span></div><i>↝</i><div class="flow-step"><b>02</b><span>找到單字家族<small>圖片＋英文＋中文，連成三格</small></span></div><i>↝</i><div class="flow-step"><b>03</b><span>走向下一章<small>收下星星，跟夥伴繼續出發</small></span></div></section><div class="section-head"><div><span class="eyebrow">PULL A RIBBON. CHOOSE A WORLD.</span><h2>你的下一頁，想讀什麼？</h2></div><button class="text-btn" data-go="map">翻閱全部二十章 ↗</button></div><div class="story-shelf">${themes.slice(0,10).map((world,i)=>`<button class="story-book" data-shelf="${i}" style="--cover:${['#5B4685','#7A9D6D','#3F587A','#8B3A3A','#E08244'][i%5]}"><span class="shelf-ribbon"></span><small>${String(i+1).padStart(2,'0')}</small><b>${world.name}</b><span>${world.emoji}</span></button>`).join('')}</div><div class="book-margin-notes"><button class="feature-card" id="continue"><span class="big-emoji">${t.emoji}</span><h3>繼續讀 · ${t.name}</h3><p>第 ${themeIndex+1} 章，留在你上次的那一頁。</p><span class="arrow">↗</span></button><button class="feature-card" data-go="review"><span class="big-emoji">✎</span><h3>口袋裡，還有幾個單字。</h3><p>${Object.keys(data.review).length?`有 ${Object.keys(data.review).length} 位單字朋友，等你再見一次。`:'收藏好奇的單字，下次再見一面。'}</p><span class="arrow">↗</span></button><button class="feature-card" data-go="multi"><span class="big-emoji">♧</span><h3>有朋友，故事就更長了。</h3><p>邀請一位夥伴，來場友善的小挑戰。</p><span class="arrow">↗</span></button></div><div class="footer-note">單字奇遇記 · THE LITTLE WORD PRESS · 給好奇的小朋友，也給陪伴他們的大朋友。</div>`);$('#adventure').onclick=()=>show('map');$('#how-to-play').onclick=help;$('#continue').onclick=()=>preview(level);document.querySelectorAll('[data-shelf]').forEach(button=>button.onclick=()=>{themeIndex=+button.dataset.shelf;try{localStorage.setItem('wordpop-world',String(themeIndex))}catch{}show('map')});bindCommon()}

function map(){
 const tones=themes.map((_,i)=>['#F7DE83','#FBE7A0','#FFF2B8','#F5D58D','#F4DF9A'][i%5]);
 const points=themes.map((t,i)=>({x:[27,66,37,70,32][i%5],y:100+i*145})),height=points.at(-1).y+130;
 let d=`M ${points[0].x*6} ${points[0].y}`;for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],mid=(a.y+b.y)/2;d+=` C ${a.x*6} ${mid} ${b.x*6} ${mid} ${b.x*6} ${b.y}`}
 shell(`${heading('THE STORY ATLAS · CHAPTERS 01—20','下一頁，從這裡展開。','挑一個主題章節，跟著夥伴走過去。每章都有四個小挑戰。',`<button class="btn small secondary" id="choose-character">${character().icon} 選擇夥伴</button>`)}<div class="map-layout"><section class="map-world journey-world" id="journey-world" style="--scene:${tones[themeIndex]}"><div class="journey-scene-caption"><span id="scene-icon">${themes[themeIndex].emoji}</span><div><small>THE NEXT CHAPTER</small><b id="scene-name">第 ${themeIndex+1} 章 · ${themes[themeIndex].name}</b></div><span class="journey-tip">點主題，角色就會走過去</span></div><div class="journey-scroll" id="journey-scroll"><div class="journey-canvas" style="height:${height}px"><svg class="journey-path" viewBox="0 0 600 ${height}" preserveAspectRatio="none" aria-hidden="true"><path d="${d}" fill="none" stroke="#c8d7ba" stroke-width="37" stroke-linecap="round"/><path d="${d}" fill="none" stroke="#fffaf0" stroke-width="27" stroke-linecap="round"/><path id="journey-track" d="${d}" fill="none" stroke="#bdce9e" stroke-width="9" stroke-linecap="round"/><path d="${d}" fill="none" stroke="#ffffffb0" stroke-width="2" stroke-dasharray="3 11"/></svg>${themes.map((t,i)=>{const passed=[1,2,3,4].filter(n=>data.stars[i*4+n]).length;return `<button class="journey-node ${i===themeIndex?'active':''} ${passed?'visited':''}" data-world="${i}" data-chapter="${i}" aria-label="第 ${i+1} 章 ${t.name}，${passed}/4 個挑戰完成" aria-pressed="${i===themeIndex}" style="left:${points[i].x}%;top:${points[i].y}px"><span class="journey-theme-icon">${t.emoji}</span><i class="journey-number">${i+1}</i><span class="journey-label ${points[i].x>50?'on-left':''}"><b>${t.name}</b><small>第 ${i+1} 章${passed?' · '+passed+'/4 已完成':''}</small></span></button><span class="journey-flower" aria-hidden="true" style="left:${points[i].x>50?18:83}%;top:${points[i].y+40}px">${['🌼','🌱','✦','🍀'][i%4]}</span>`}).join('')}<div class="map-walker journey-walker" id="map-walker" aria-label="${esc(character().name)}，目前在第 ${themeIndex+1} 章" style="left:${points[themeIndex].x}%;top:${points[themeIndex].y-61}px;background:${character().color}"><span>${character().icon}</span><i>▼</i></div></div></div></section><aside class="map-aside" id="journey-aside"></aside></div>`);
 map.points=points;map.height=height;map.tones=tones;map.position=themeIndex;map.walking=false;
 $('#choose-character').onclick=chooseCharacter;document.querySelectorAll('[data-chapter]').forEach(button=>button.onclick=()=>selectJourney(+button.dataset.chapter,true));renderJourneyAside();
 const path=$('#journey-track'),length=path.getTotalLength();path.style.strokeDasharray=length;path.style.strokeDashoffset=length-journeyDistance(themeIndex);$('#journey-scroll').scrollTop=Math.max(0,points[themeIndex].y-220);bindCommon();
}
function journeyDistance(index){const path=$('#journey-track');if(!path||!map.points)return 0;const total=path.getTotalLength(),target=map.points[index];let best=0,error=Infinity;for(let step=0;step<=600;step++){const at=total*step/600,p=path.getPointAtLength(at),distance=(p.x-target.x*6)**2+(p.y-target.y)**2;if(distance<error){error=distance;best=at}}return best}
function renderJourneyAside(){const t=themes[themeIndex],base=themeIndex*4;$('#journey-aside').innerHTML=`<div class="panel"><div class="eyebrow">CHAPTER ${String(themeIndex+1).padStart(2,'0')} / 20</div><div class="chapter-art">${t.emoji}</div><h3>第 ${themeIndex+1} 章 · ${t.name}</h3><p>先認識這一章的單字朋友，<br>再挑一個小挑戰。</p><div class="word-chips">${t.words.map(w=>`<button class="word-chip" data-speak="${esc(w.en)}">${esc(w.emoji)} ${esc(w.en)}</button>`).join('')}</div><div class="chapter-challenges" aria-label="${t.name}四個挑戰">${[1,2,3,4].map(n=>`<button data-challenge="${base+n}"><span>${n===4?'♛':n}</span><small>${n===4?'Boss':'挑戰 '+n}</small>${data.stars[base+n]?`<i>${'★'.repeat(data.stars[base+n])}</i>`:''}</button>`).join('')}</div><button class="btn" id="journey-play">翻開這一章 ↗</button><button class="text-btn" id="practice-world" style="width:100%;margin-top:15px">先練習，不計分</button></div><div class="study-tip"><b>${character().icon} ${character().name}的小提醒</b>直接點路上的主題，跟我一起走過去。<br>每一關上方的圖案，都是那一站的主題。</div>`;document.querySelectorAll('[data-challenge]').forEach(b=>b.onclick=()=>preview(+b.dataset.challenge));$('#journey-play').onclick=()=>preview(base+1);$('#practice-world').onclick=()=>preview(base+1,true);bindCommon()}
async function selectJourney(index,openPreview=false){if(page!=='map'||map.walking||index<0||index>=20)return;const walker=$('#map-walker'),world=$('#journey-world'),scroll=$('#journey-scroll'),path=$('#journey-track');if(!walker||!world||!path)return;map.walking=true;const from=map.position,fromLength=journeyDistance(from),toLength=journeyDistance(index),total=path.getTotalLength(),width=$('.journey-canvas').clientWidth;themeIndex=index;try{localStorage.setItem('wordpop-world',String(index))}catch{}world.style.setProperty('--scene',map.tones[index]);$('#scene-icon').textContent=themes[index].emoji;$('#scene-name').textContent=`第 ${index+1} 章 · ${themes[index].name}`;document.querySelectorAll('[data-chapter]').forEach(b=>{const active=+b.dataset.chapter===index;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});renderJourneyAside();path.style.stroke= ['#5B4685','#E08244','#C23D3D','#7A9D6D','#3F587A'][index%5];path.style.strokeDashoffset=total-toLength;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;scroll.scrollTo({top:Math.max(0,map.points[index].y-scroll.clientHeight/2),behavior:reduced?'instant':'smooth'});
 if(!reduced){const frames=[];for(let i=0;i<=50;i++){const p=path.getPointAtLength(fromLength+(toLength-fromLength)*i/50);frames.push({left:p.x/600*width+'px',top:p.y-61+'px'})}walker.classList.add('walking');const motion=walker.animate(frames,{duration:from===index?250:Math.min(1800,750+Math.abs(index-from)*170),easing:'cubic-bezier(.25,.65,.3,1)',fill:'forwards'});try{await motion.finished}catch{}motion.cancel();if(!world.isConnected){map.walking=false;return}}
 walker.style.left=map.points[index].x+'%';walker.style.top=map.points[index].y-61+'px';walker.setAttribute('aria-label',`${character().name}，目前在第 ${index+1} 章 ${themes[index].name}`);walker.classList.remove('walking');map.position=index;map.walking=false;if(openPreview&&page==='map'&&world.isConnected)preview(index*4+1);
}

function config(level){const stage=(level-1)%4;return {stage,moves:[20,21,23,25][stage],target:[10,12,18,24][stage],ice:stage===3?4:0,locks:stage===2?4:0,family:stage===0?0:stage===1?1:-1}}
function goalText(c,t){return `消除 ${c.target} 個${c.family>=0?esc(t.words[c.family].en):'單字'}方塊${c.ice?'，並解凍 4 個冰塊':c.locks?'，並解開 4 條鎖鏈':''}`}
function preview(level,practice=false){const t=themes[Math.floor((level-1)/4)],c=config(level);modal(`<div class="modal-hero">${t.emoji}</div><div class="eyebrow" style="text-align:center">第 ${Math.floor((level-1)/4)+1} 章 · 挑戰 ${(level-1)%4+1} / 4 ${c.stage===3?'· BOSS CHALLENGE':''}</div><h2 style="text-align:center">${t.name}${c.stage===3?'守護者':'小冒險'}</h2><p style="text-align:center">${goalText(c,t)}<br>你有 ${c.moves} 步，慢慢想也沒關係。</p><div class="word-chips" style="justify-content:center">${t.words.map(w=>`<button class="word-chip" data-speak="${esc(w.en)}">${esc(w.emoji)} ${esc(w.en)}</button>`).join('')}</div><div class="example" style="margin:15px 0"><b>${t.words[0].emoji}</b><b>${esc(t.words[0].en)}</b><b>${esc(t.words[0].zh)}</b></div><p style="text-align:center">同一單字的圖像、英文、中文可以混搭消除。</p><div class="stat-row"><span>新手顏色提示</span><b>${Math.floor((level-1)/4)>=15?'高階主題關閉':data.settings.color?'開啟':'關閉'}</b></div><label class="settings-row"><span><b>帶上發音提示卡</b><small>進入後自動朗讀第一個單字，免費。</small></span><input type="checkbox" id="bring-sound" checked></label><button class="btn" id="start-level">開始冒險 <span>→</span></button><button class="btn secondary" id="cancel-level">再準備一下</button>`);$('#start-level').onclick=()=>{const audio=$('#bring-sound').checked;closeModal();startLevel(level,{audio,practice})};$('#cancel-level').onclick=closeModal;bindCommon()}
async function startLevel(level,options={}){if(!qaRunning&&!options.online&&data.seconds>=data.settings.limit*60){toast('今天已達設定的練習時間，休息一下再回來。');return}const t=themes[Math.floor((level-1)/4)],c=config(level);const maxWord=Math.max(...t.words.map(w=>w.en.length));SIZE=options.online?6:maxWord>6?5:6;const rng=seeded(options.seed||Math.floor(Math.random()*2147483646)+1);let board=newBoard(SIZE,6,rng);if(c.ice||c.locks){const safe=possibleMoves(board,SIZE)[0]||[],positions=[7,10,25,28,...Array.from({length:SIZE*SIZE},(_,i)=>i)].filter((i,j,a)=>i<SIZE*SIZE&&!safe.includes(i)&&a.indexOf(i)===j).slice(0,4);positions.forEach(i=>{if(c.ice)board[i].ice=2;else board[i].lock=1});c.ice=c.ice?positions.length:0;c.locks=c.locks?positions.length:0;if(!possibleMoves(board,SIZE).length)board=shuffleBoard(board,SIZE,6,rng)}game={id:Date.now(),level,t,c,rng,board,moves:c.moves,score:0,cleared:0,progress:0,obstacles:0,ended:false,paused:false,online:!!options.online,practice:!!options.practice,reviewOnly:!!options.reviewOnly,lastWord:t.words[0],hint:[],startAt:Date.now(),activeSeconds:0,attempts:0,successes:0,seen:new Set(),extended:false,onlineDone:false};if(game.online){game.moves=999;game.c={...c,target:9999,ice:0,locks:0,family:-1}}page='loading';shell(`<div class="load-screen"><div class="load-tiles"><span>${t.emoji}</span><span>${esc(t.words[0].en)}</span><span>${esc(t.words[0].zh)}</span></div><div class="eyebrow">GETTING YOUR ADVENTURE READY</div><h2>下一站，${t.name}！</h2><p>試著用圖、英文、中文，連出同一個單字。</p><div class="progress"><i></i></div></div>`);const id=game.id;await sleep(1000);if(!game||game.id!==id||page!=='loading')return;page='game';gameView();if(options.audio)speak(t.words[0].en);if(options.online)pollRoom()}
function gameView(){const g=game;if(!g)return;shell(`${heading(g.online?'FRIENDLY WORD CHALLENGE':`第 ${Math.floor((g.level-1)/4)+1} 章 · 挑戰 ${g.c.stage+1} / 4`,`${g.t.emoji} ${g.t.name}${g.online?'好友挑戰':'小冒險'}`,g.online?'相同的起始棋盤，各自找到最棒的配對。':'橫向或直向，交換兩個相鄰方塊。',`<button class="text-btn" id="pause-top">Ⅱ 暫停</button>`)}<div class="game-layout"><div class="game-card"><div class="game-head"><div class="game-stat"><small>${g.online?'剩餘時間':'剩餘步數'}</small><b id="moves">${g.online?onlineSeconds():g.moves}</b></div><div style="text-align:center"><div class="eyebrow" style="font-size:8px">WORD POP</div><strong style="font-size:12px">${g.online?'同學一起，單字加倍':'小小配對，大大發現'}</strong></div><div class="game-stat"><small>冒險分數</small><b id="score">${g.score}</b></div></div><div class="game-goal"><span>${g.c.family>=0?g.t.words[g.c.family].emoji:'🎯'}</span><span>${g.online?'消除進度':'本關目標'}</span><div class="progress"><i id="goal-bar" style="width:0%"></i></div><strong id="goal-count">0 / ${g.online?'∞':g.c.target}</strong>${g.c.ice||g.c.locks?`<span id="obstacle-count">${g.c.ice?'❄':'🔗'} 0/${g.c.ice||g.c.locks}</span>`:''}</div><div id="board" class="board" style="--board-size:${SIZE}" role="group" aria-label="${SIZE}乘${SIZE}單字棋盤"></div><div class="tools"><button class="tool" id="speak-tool" title="朗讀選取的單字">🔊<small>聽發音 · 免費</small></button><button class="tool" id="hint-tool" title="顯示合法交換">💡<small>${g.online?'對戰不使用':'提示 · 10 幣'}</small></button><button class="tool" id="shuffle-tool" title="重新排列棋盤">🔄<small>${g.online?'對戰不使用':'重排 · 15 幣'}</small></button><button class="tool" id="pause-tool">Ⅱ<small>暫停</small></button></div><div class="footer-note" style="margin:14px 0 1px">點選兩格或滑動交換 · 無效交換不扣步數</div></div><aside class="play-aside"><div class="panel"><div class="eyebrow">A WORD TO REMEMBER</div><h3>這一次，認識了⋯⋯</h3><div id="last-word">${lastWordHTML()}</div><p>不只是消除圖案，<br>也把單字的樣子記在心裡。</p><button class="text-btn" id="save-word" style="margin-top:10px">＋ 收進單字本</button></div>${g.online?'<div class="panel"><div class="eyebrow">LIVE ROOM</div><h3>同場小夥伴</h3><div id="opponents">正在同步⋯⋯</div></div>':`<div class="panel"><div class="eyebrow">LITTLE MATCH GUIDE</div><div class="legend"><span>⚡</span>4 連：整行或整列</div><div class="legend"><span>💥</span>L / T 交叉：範圍爆炸</div><div class="legend"><span>🌈</span>5 連：消除同一家族</div><div class="legend"><span>🌟</span>幸運星：連續三次配對</div><p style="font-size:10px">圖＋英文＋中文，一起消除<br>可獲得混搭獎勵！</p></div>`}</aside></div>`);renderBoard();updateHUD();$('#pause-top').onclick=pause;$('#pause-tool').onclick=pause;$('#speak-tool').onclick=()=>speak(selected>=0?g.t.words[g.board[selected].family].en:g.lastWord.en);$('#hint-tool').onclick=hint;$('#shuffle-tool').onclick=shuffle;$('#save-word').onclick=()=>addReview(g.lastWord,'自己收藏');bindCommon()}
function lastWordHTML(){const w=game.lastWord;return `<div class="last-word"><span class="emoji">${esc(w.emoji)}</span><div><strong>${esc(w.en)}</strong><small>${esc(w.zh)}</small></div><button class="icon" data-speak="${esc(w.en)}" aria-label="朗讀 ${esc(w.en)}">♫</button></div>`}
function renderBoard(extra={}){
 const g=game,board=$('#board');if(!g||!board)return;
 const focused=board.contains(document.activeElement)?+document.activeElement.dataset.cell:null;const moving=!!(extra.swap||extra.drop);const oldPositions=new Map((moving?[...board.children]:[]).filter(el=>el.dataset.uid).map(el=>[el.dataset.uid,el.getBoundingClientRect()]));
 const existing=new Map([...board.children].filter(el=>el.dataset.uid).map(el=>[el.dataset.uid,el]));
 const keep=new Set();
 g.board.forEach((tile,i)=>{
   const uid=String(tile.id||`fallback-${i}`),w=g.t.words[tile.family],type=Math.floor((g.level-1)/4)>=15&&tile.type===0?1:tile.type;
   const content=type===0?w.emoji:type===1?w.en:w.zh,col=data.settings.color&&Math.floor((g.level-1)/4)<15?(Math.floor((g.level-1)/4)===2?['#f5c6ca','#c6dff5','#f8e69b','#d2e8bb','#dfd0f3','#f4d1ad'][tile.family]:colors[tile.family]):'#f1e7cd';
   let el=existing.get(uid);if(!el){el=document.createElement('button');el.dataset.uid=uid;el.innerHTML='<span class="tile-label"></span><span class="special"></span><span class="obstacle"></span>'}
   keep.add(el);el.className=`tile type${type} ${content.length>8?'long':''} ${selected===i?'selected':''} ${g.hint.includes(i)?'hint':''} ${extra.pop?.includes(i)?'pop':''} ${extra.wrong?.includes(i)?'wrong':''} ${tile.lock?'locked':''}`;
   el.style.setProperty('--tile',col);el.setAttribute('role','button');el.tabIndex=i===(focused??(selected>=0?selected:0))?0:-1;el.setAttribute('aria-pressed',String(selected===i));el.dataset.cell=i;
   el.setAttribute('aria-label',`第 ${Math.floor(i/SIZE)+1} 排第 ${i%SIZE+1} 格，${type===0?'圖片 '+w.en:content}${tile.special?'，特殊方塊 '+tile.special:''}${tile.ice?'，冰塊剩 '+tile.ice+' 層':tile.lock?'，鎖鏈':''}`);el.disabled=g.ended;
   el.querySelector('.tile-label').textContent=content;el.querySelector('.tile-label').lang=type===1?'en':'zh-Hant';
   const special=el.querySelector('.special');special.textContent=({line:'⚡',bomb:'💥',rainbow:'🌈',star:'🌟'})[tile.special]||'';special.hidden=!tile.special;
   const obstacle=el.querySelector('.obstacle');obstacle.textContent=tile.ice?'❄️ '+tile.ice:tile.lock?'🔗':'';obstacle.hidden=!(tile.ice||tile.lock);
   if(board.children[i]!==el)board.insertBefore(el,board.children[i]||null);
 });
 for(const el of [...board.children])if(!keep.has(el))el.remove();
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const cellWidth=(board.clientWidth-18-(SIZE-1)*6)/SIZE;
 for(const el of board.children){fitLabel(el,cellWidth);if(!reduced&&moving){const old=oldPositions.get(el.dataset.uid),now=el.getBoundingClientRect();if(old){const dx=old.left-now.left,dy=old.top-now.top;if(Math.abs(dx)+Math.abs(dy)>1)el.animate([{translate:`${dx}px ${dy}px`},{translate:'0 0'}],{duration:extra.swap?180:340,easing:'cubic-bezier(.2,.8,.25,1)'});}else if(extra.drop)el.animate([{translate:`0 -${Math.max(60,now.height*(Math.floor(+el.dataset.cell/SIZE)+1))}px`,opacity:0},{translate:'0 0',opacity:1}],{duration:360,easing:'cubic-bezier(.18,.8,.25,1)'});}}
 if(focused!==null)board.querySelector(`[data-cell="${focused}"]`)?.focus({preventScroll:true});
 if(!board.resizeWatcher){board.resizeWatcher=new ResizeObserver(()=>{const width=(board.clientWidth-18-(SIZE-1)*6)/SIZE;for(const el of board.children)fitLabel(el,width)});board.resizeWatcher.observe(board);}
 if(extra.pop&&!reduced)for(const i of extra.pop){const el=board.querySelector(`[data-cell="${i}"]`);if(el)burst(el)}
 if(board.dataset.bound)return;board.dataset.bound='1';let down=null,suppress=false;
 board.onpointerdown=e=>{if(busy||game.paused||game.ended)return;const b=e.target.closest('[data-cell]');if(!b)return;down={i:+b.dataset.cell,x:e.clientX,y:e.clientY};};
 board.onpointerup=e=>{if(!down)return;const d=down;down=null;const dx=e.clientX-d.x,dy=e.clientY-d.y;if(Math.hypot(dx,dy)>18){suppress=true;const to=Math.abs(dx)>Math.abs(dy)?d.i+(dx>0?1:-1):d.i+(dy>0?SIZE:-SIZE);if(to>=0&&to<SIZE*SIZE&&Math.abs(Math.floor(d.i/SIZE)-Math.floor(to/SIZE))+Math.abs(d.i%SIZE-to%SIZE)===1)move(d.i,to);setTimeout(()=>suppress=false,80)}};
 board.onpointercancel=()=>down=null;board.onclick=e=>{if(suppress)return;const b=e.target.closest('[data-cell]');if(b)cell(+b.dataset.cell)};
 board.onkeydown=e=>{const b=e.target.closest('[data-cell]');if(!b)return;const i=+b.dataset.cell,d={ArrowLeft:-1,ArrowRight:1,ArrowUp:-SIZE,ArrowDown:SIZE}[e.key];if(d){e.preventDefault();const to=i+d;if(to>=0&&to<SIZE*SIZE&&(Math.abs(d)===SIZE||Math.floor(to/SIZE)===Math.floor(i/SIZE))){if(e.shiftKey)move(i,to);else{board.querySelectorAll('[data-cell]').forEach(x=>x.tabIndex=-1);const next=board.querySelector(`[data-cell="${to}"]`);next.tabIndex=0;next.focus()}}}};
}
const fitCache=new Map();let measureCtx;
function fitLabel(el,width){const label=el.querySelector('.tile-label');if(!label||!el.classList.contains('type1')||width<15)return;const key=label.textContent+'|'+Math.round(width);let fit=fitCache.get(key);if(!fit){measureCtx??=document.createElement('canvas').getContext('2d');const max=width-10;let size=18,measured=0;while(size>=10){measureCtx.font=`700 ${size}px Inter, sans-serif`;measured=measureCtx.measureText(label.textContent).width;if(measured<=max||size===10)break;size-=.5}fit={size,scale:Math.min(1,(width-8)/Math.max(1,measured))};fitCache.set(key,fit)}label.style.fontSize=fit.size+'px';label.style.scale=`${fit.scale} 1`;}

function specialFX(frame){const board=$('#board');if(!board)return;for(const i of frame.cleared){const tile=frame.before[i];if(!tile?.special)continue;const el=board.querySelector(`[data-cell="${i}"]`);if(!el)continue;const r=el.getBoundingClientRect(),br=board.getBoundingClientRect(),fx=document.createElement('div');fx.className='special-fx '+tile.special;fx.style.cssText=`left:${r.left+r.width/2}px;top:${r.top+r.height/2}px;--fxw:${br.width}px;--fxh:${br.height}px;--cell:${r.width}px`;if(tile.special==='line'){if(tile.axis==='col')fx.style.top=br.top+br.height/2+'px';else fx.style.left=br.left+br.width/2+'px';fx.style.width=tile.axis==='col'?'8px':br.width+'px';fx.style.height=tile.axis==='col'?br.height+'px':'8px'}document.body.append(fx);setTimeout(()=>fx.remove(),650)}}

function burst(el){const r=el.getBoundingClientRect();for(let j=0;j<7;j++){const p=document.createElement('i');p.className='tile-particle';p.style.cssText=`left:${r.left+r.width/2}px;top:${r.top+r.height/2}px;background:${colors[j%6]}`;document.body.append(p);const a=j/7*Math.PI*2,d=25+Math.random()*25;const motion=p.animate([{translate:'0 0',scale:1,opacity:1},{translate:`${Math.cos(a)*d}px ${Math.sin(a)*d}px`,scale:.2,opacity:0}],{duration:420,easing:'ease-out'});motion.onfinish=()=>p.remove()}}

function cell(i){if(busy||game.paused||game.ended||$('.modal'))return;if(game.board[i].ice||game.board[i].lock){toast('先消除相鄰的配對，才能解開這一格。');return}if(selected===i){selected=-1;renderBoard();return}if(selected>=0){const prev=selected;selected=-1;if(Math.abs(Math.floor(prev/SIZE)-Math.floor(i/SIZE))+Math.abs(prev%SIZE-i%SIZE)===1){move(prev,i);return}}selected=i;game.hint=[];game.lastWord=game.t.words[game.board[i].family];renderBoard();updateWord();}
async function move(a,b){const g=game;if(!g||busy||g.paused||g.ended)return;if(g.online&&onlineSeconds()<=0){submitScore(true);return}busy=true;selected=-1;g.hint=[];g.attempts++;const result=applyMove(g.board,SIZE,a,b,6,g.rng,{luckyChance:g.online?0:g.c.stage===3?.1:.05});if(!result.valid){sound('wrong');renderBoard({wrong:[a,b]});toast('這次還沒連成同一家族，步數沒有減少。');await sleep(320);renderBoard();$(`[data-cell="${a}"]`)?.focus({preventScroll:true});busy=false;return}g.successes++;if(!g.online)g.moves--;const rootID=g.id,baseScore=g.score,moveStarted=performance.now();let frameScore=0;for(const [frameIndex,frame] of result.frames.entries()){if(game?.id!==rootID){busy=false;return}g.board=frame.before;const swapping=frameIndex===0||frame.automatic;renderBoard({swap:swapping});if(swapping)await sleep(180);specialFX(frame);renderBoard({pop:frame.cleared});frameScore+=frame.score;g.score=baseScore+frameScore;updateHUD();sound();if(frameIndex===0&&frame.combo===1)combo('+'+frame.score);if(frame.automatic)combo('幸運星！🌟');else if(frame.combo>1)combo(`連鎖 ×${frame.combo} ✦`);await sleep(260);g.board=frame.after;renderBoard({drop:true});await sleep(380)}if(g.online)await new Promise(resolve=>setTimeout(resolve,Math.max(0,result.frames.length*820-(performance.now()-moveStarted))));g.board=result.board;g.score=baseScore+result.score;g.cleared+=result.cleared;g.obstacles+=result.obstacles;const counts=result.words;g.progress+=g.c.family>=0?(counts[g.c.family]||0):result.cleared;Object.keys(counts).forEach(f=>g.seen.add(+f));const fam=Object.keys(counts).sort((a,b)=>counts[b]-counts[a])[0];if(fam!==undefined){g.lastWord=g.t.words[+fam];speak(g.lastWord.en)}if(result.reshuffled)toast('沒有可配對的組合，已為你自動重排。');renderBoard();$(`[data-cell="${b}"]`)?.focus({preventScroll:true});updateHUD();updateWord();if($('#announcer'))$('#announcer').textContent=`成功消除 ${result.cleared} 個方塊，獲得 ${result.score} 分，剩餘 ${g.online?onlineSeconds()+'秒':g.moves+'步'}。`;busy=false;if(result.luckySpawn!==null&&result.luckySpawn!==undefined)toast('幸運星來了！配對消除它，會自動連續配對三次。');if(g.online){await submitScore(false);return}if(g.progress>=g.c.target&&g.obstacles>=(g.c.ice||g.c.locks)){win();return}if(g.moves<=0)lose()}
function combo(text){const c=document.createElement('div');c.className='combo';c.textContent=text;$('.game-card')?.append(c);setTimeout(()=>c.remove(),850)}
function updateWord(){if($('#last-word')){$('#last-word').innerHTML=lastWordHTML();bindCommon()}}
function updateHUD(){const g=game;if(!g||!$('#score'))return;$('#score').textContent=g.score;$('#moves').textContent=g.online?onlineSeconds():g.moves;$('#goal-count').textContent=`${Math.min(g.progress,g.c.target)} / ${g.online?'∞':g.c.target}`;$('#goal-bar').style.width=`${g.online?Math.min(100,g.cleared/120*100):Math.min(100,g.progress/g.c.target*100)}%`;if($('#obstacle-count'))$('#obstacle-count').textContent=`${g.c.ice?'❄':'🔗'} ${g.obstacles}/${g.c.ice||g.c.locks}`;if($('#coins'))$('#coins').textContent=data.coins;if($('#hint-tool'))$('#hint-tool').disabled=g.online;if($('#shuffle-tool'))$('#shuffle-tool').disabled=g.online}
function hint(){if(busy||game.ended||game.paused||game.online)return;if(data.coins<10){toast('提示需要 10 枚硬幣，過關就能收集硬幣。');return}const pair=possibleMoves(game.board,SIZE)[0];if(!pair){toast('棋盤正在準備重排。');return}data.coins-=10;save();game.hint=pair;renderBoard();updateHUD();toast('看看發光的兩格，交換後會發生什麼事？')}
function shuffle(){if(busy||game.ended||game.paused||game.online)return;if(data.coins<15){toast('重排需要 15 枚硬幣。');return}data.coins-=15;save();game.board=shuffleBoard(game.board,SIZE,6,game.rng);game.hint=[];selected=-1;renderBoard({drop:true});updateHUD();sound()}
function pause(){if(busy||game?.ended)return;if(game.online){toast('即時對戰時間會繼續；你可以離開這場挑戰。');return}game.paused=true;modal(`<div class="modal-hero">☕</div><h2>冒險，偶爾也需要休息。</h2><p>棋盤會在這裡等你。深呼吸，再出發吧。</p><button class="btn" id="resume">繼續冒險</button><button class="btn secondary" id="quit">回到地圖</button>`,()=>{if(game)game.paused=false});$('#resume').onclick=closeModal;$('#quit').onclick=()=>{record(false);game.ended=true;closeModal();themeIndex=Math.floor((game.level-1)/4);show('map')}}
function record(won){const g=game;if(g.recorded)return;g.recorded=true;data.history.unshift({level:g.level,theme:g.t.name,score:g.score,won,seconds:g.activeSeconds,cleared:g.cleared,attempts:g.attempts,successes:g.successes,words:[...g.seen].map(f=>g.t.words[f].en),at:new Date().toISOString(),online:g.online,practice:g.practice});data.history=data.history.slice(0,200);save()}
function confetti(){for(let i=0;i<32;i++){const p=document.createElement('span');p.className='confetti';p.style.cssText=`--x:${Math.random()*100}vw;--c:${colors[i%6]};--d:${1.8+Math.random()*2}s;animation-delay:${Math.random()*.3}s`;document.body.append(p);setTimeout(()=>p.remove(),4500)}}
function win(){const g=game;g.ended=true;record(true);const stars=g.moves>=g.c.moves*.45?3:g.moves>=g.c.moves*.2?2:1;const oldStars=data.stars[g.level]||0;if(!g.practice)data.stars[g.level]=Math.max(oldStars,stars);const coins=g.practice?0:oldStars?10:30;data.coins+=coins;if(!g.practice&&g.level===data.unlocked&&g.level<80){data.unlocked++;lastUnlock=data.unlocked}save();if(!qaRunning&&!g.practice)uploadRun({runId:crypto.randomUUID(),level:g.level,score:g.score,stars,seconds:g.activeSeconds,cleared:g.cleared});sound('win');confetti();renderBoard();modal(`<div class="result"><div class="eyebrow">A LITTLE VICTORY</div><h2>${g.level===80?'你的單字旅程，閃閃發亮！':'太棒了，你又前進了一小步！'}</h2><div class="stars">${[1,2,3].map(i=>`<span style="color:${i<=stars?'#e7b64f':'#e1dfd4'}">★</span>`).join('')}</div><p>${g.t.name}的單字夥伴，都為你鼓掌！${g.practice?'<br>自由體驗不改變冒險進度，也不計入排行榜。':''}</p><div class="stat-row"><span>冒險分數</span><b>${g.score}</b></div><div class="stat-row"><span>收集硬幣</span><b>🪙 +${coins}</b></div><div class="stat-row"><span>剩餘步數</span><b>${g.moves} 步</b></div>${g.level<80?`<button class="btn" id="next-level">${g.practice?'回到主題地圖':'下一個小冒險 →'}</button>`:'<button class="btn" id="next-level">回顧我的學習足跡 →</button>'}<button class="btn secondary" id="back-map">回到單字地圖</button></div>`,null,false);$('#next-level').onclick=()=>{closeModal();if(g.practice){themeIndex=Math.floor((g.level-1)/4);show('map')}else if(g.level<80){themeIndex=Math.floor((g.level-1)/4);show('map');selectJourney(Math.min(19,themeIndex+1),true)}else show('report')};$('#back-map').onclick=()=>{closeModal();themeIndex=Math.floor((g.level-1)/4);show('map');if(!g.practice)selectJourney(Math.min(19,themeIndex+1),false)}}
function lose(){const g=game;modal(`<div class="modal-hero">🌱</div><h2>還差一點點，再試一次吧。</h2><p>每次練習，都在讓單字變得更熟悉。<br>已完成 ${Math.min(g.progress,g.c.target)} / ${g.c.target} 個目標方塊。</p><button class="btn" id="retry-level">重新挑戰這一關</button>${!g.extended?'<button class="btn secondary" id="extra-moves">領取一次免費 +5 步</button>':''}<button class="btn secondary" id="fail-map">先休息，回到地圖</button>`,null,false);$('#retry-level').onclick=()=>{record(false);g.ended=true;closeModal();startLevel(g.level,{practice:g.practice})};if($('#extra-moves'))$('#extra-moves').onclick=()=>{g.extended=true;g.moves=5;closeModal();updateHUD()};$('#fail-map').onclick=()=>{record(false);g.ended=true;closeModal();themeIndex=Math.floor((g.level-1)/4);show('map')}}
function addReview(w,reason='小測驗待複習'){data.review[wordKey(w)]={...w,reason,at:new Date().toISOString()};save();toast(`已把 ${w.en} 放進單字本。`)}
function review(){const entries=Object.values(data.review);shell(`${heading('YOUR POCKET WORDS','把單字，放進口袋。','遊戲的錯誤交換不代表單字答錯。這裡記錄你收藏、或小測驗中待複習的單字。',`<button class="btn small secondary" id="quiz-all">單字小測驗 →</button>`)}<div class="tabs"><button class="active" id="review-tab">待複習 ${entries.length}</button><button id="all-words-tab">20 主題單字庫</button></div><div id="words-container">${entries.length?wordCards(entries):`<div class="empty"><div class="empty-icon">📔</div><h3>這一頁，留給新的發現。</h3><p>遊戲中可以把單字收進來，<br>也可以做一個小測驗，找出想再複習的單字。</p><button class="btn" id="first-quiz">來一個小測驗</button></div>`}</div>`);$('#quiz-all').onclick=()=>quiz();$('#first-quiz')&&($('#first-quiz').onclick=()=>quiz());$('#review-tab').onclick=review;$('#all-words-tab').onclick=()=>{document.querySelectorAll('.tabs button').forEach(b=>b.classList.remove('active'));$('#all-words-tab').classList.add('active');$('#words-container').innerHTML=`<select class="theme-select" id="word-theme" style="margin-bottom:20px">${themes.map((t,i)=>`<option value="${i}">${t.emoji} ${t.name}</option>`).join('')}</select><div id="catalog">${wordCards(themes[0].words,true)}</div>`;$('#word-theme').onchange=e=>{$('#catalog').innerHTML=wordCards(themes[+e.target.value].words,true);bindWords()};bindWords()};bindWords()}
function wordCards(words,catalog=false){return `<div class="word-grid">${words.map(w=>`<article class="word-card"><span class="emoji">${esc(w.emoji)}</span><h3>${esc(w.en)}</h3><p>${esc(w.zh)}</p><small>${catalog?'圖像・英文・中文':esc(w.reason)}</small><div class="actions"><button class="icon" data-speak="${esc(w.en)}" aria-label="朗讀 ${esc(w.en)}">♫</button><button class="text-btn" data-quiz="${esc(wordKey(w))}">練習一下 →</button>${catalog?`<button class="text-btn" data-save="${esc(wordKey(w))}">＋</button>`:''}</div></article>`).join('')}</div>`}
const allWords=()=>themes.flatMap(t=>t.words);
const wordKey=w=>w.en+'::'+w.zh;
function bindWords(){bindCommon();document.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=()=>quiz(allWords().find(w=>wordKey(w)===b.dataset.quiz)));document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>addReview(allWords().find(w=>wordKey(w)===b.dataset.save)))}
function quiz(fixed){const bank=Object.values(data.review).length?Object.values(data.review):themes[Math.min(19,Math.floor((data.unlocked-1)/4))].words;const w=fixed||bank[Math.floor(Math.random()*bank.length)],choices=[w,...[...new Map(allWords().filter(x=>x.en!==w.en).map(x=>[x.en,x])).values()].sort(()=>Math.random()-.5).slice(0,3)].sort(()=>Math.random()-.5);modal(`<div class="eyebrow">A LITTLE WORD CHECK</div><h2>「${esc(w.zh)}」的英文是？</h2><p>試著先回想，再選一個答案。</p><div class="modal-hero">${esc(w.emoji)}</div><div id="quiz-choices">${choices.map(c=>`<button class="btn secondary" data-answer="${esc(c.en)}">${esc(c.en)}</button>`).join('')}</div><div id="quiz-feedback" role="status" aria-live="polite"></div>`);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);const ok=b.dataset.answer===w.en;data.quiz[wordKey(w)]??={right:0,wrong:0};data.quiz[wordKey(w)][ok?'right':'wrong']++;if(ok){delete data.review[wordKey(w)];sound('win')}else{addReview(w);sound('wrong')}save();speak(w.en);$('#quiz-feedback').innerHTML=`<p style="color:${ok?'#56733f':'#a26b50'}">${ok?'答對了！已完成這次複習。':`一起記住：${esc(w.en)} 是「${esc(w.zh)}」。已加入待複習。`}</p><button class="btn" id="quiz-next">再認識一個 →</button>`;$('#quiz-next').onclick=()=>quiz()})}
function report(){const h=data.history,seen=new Set(h.flatMap(x=>x.words)),quizzes=Object.values(data.quiz),right=quizzes.reduce((a,x)=>a+x.right,0),wrong=quizzes.reduce((a,x)=>a+x.wrong,0);shell(`${heading('SMALL STEPS, REAL PROGRESS','每一小步，都留下足跡。','遊戲紀錄與單字測驗分開看，才能看見真正的學習。',`<button class="btn small secondary" id="export">匯出紀錄 ↓</button>`)}<div class="report-grid"><div class="metric"><small>完成關卡</small><b>${Object.keys(data.stars).length}<span style="font-size:13px;color:#a5ae99"> / 80</span></b><em>持續前進的小腳印</em></div><div class="metric"><small>遊戲中遇見的單字</small><b>${seen.size}</b><em>接觸次數不等於已學會</em></div><div class="metric"><small>單字測驗答對率</small><b>${right+wrong?Math.round(right/(right+wrong)*100)+'%':'—'}</b><em>${right+wrong} 次實際作答</em></div><div class="metric"><small>今天專心練習</small><b>${Math.floor(data.seconds/60)}<span style="font-size:13px;color:#a5ae99"> 分鐘</span></b><em>建議練習後起身休息</em></div></div><div class="panel"><div class="section-head" style="margin-top:0"><h2>最近的冒險</h2><small>最近 ${Math.min(20,h.length)} 場</small></div>${h.length?`<div class="table-wrap"><table><thead><tr><th>主題 / 關卡</th><th>結果</th><th>分數</th><th>有效配對</th><th>練習日期</th></tr></thead><tbody>${h.slice(0,20).map(x=>`<tr><td>${esc(x.theme)} · ${x.level}</td><td>${x.won?'⭐ 完成':'🌱 練習中'}</td><td>${x.score}</td><td>${x.successes} / ${x.attempts}</td><td>${new Date(x.at).toLocaleDateString('zh-TW')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><div class="empty-icon">🌱</div><h3>第一步，隨時可以開始。</h3><p>完成第一場冒險後，紀錄就會出現在這裡。</p><button class="btn" data-go="map">去單字地圖 →</button></div>'}</div><div class="daily-strip"><span class="daily-icon">🧑‍🏫</span><div><b>給老師與家長的小筆記</b><p>目前是這台裝置的練習紀錄；匯出 CSV 可用於課堂觀察。尚未綁定學生帳號與雲端班級。</p></div></div>`);$('#export').onclick=exportCSV;bindCommon()}
function exportCSV(){const rows=[['日期','主題','關卡','完成','分數','有效交換','交換嘗試','接觸單字','秒數'],...data.history.map(h=>[h.at,h.theme,h.level,h.won?'是':'否',h.score,h.successes,h.attempts,h.words.join(' / '),h.seconds])];const text='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v).replace(/^(?=[\s]*[=+@-])/,"'").replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));a.download='word-pop-learning.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function settings(){shell(`${heading('MAKE IT YOUR OWN','用舒服的方式，學習。','聲音、提示與時間，都照你的步調來。')}<div class="panel" style="max-width:700px"><label class="settings-row"><span><b>發音與音效</b><small>使用裝置內建英文語音；離線是否可用依裝置而定。</small></span><input type="checkbox" id="sound-setting" ${data.settings.sound?'checked':''}></label><label class="settings-row"><span><b>英文發音偏好</b><small>會優先使用可用的對應口音語音。</small></span><select id="accent"><option value="en-US" ${data.settings.accent==='en-US'?'selected':''}>美式英語</option><option value="en-GB" ${data.settings.accent==='en-GB'?'selected':''}>英式英語</option></select></label><label class="settings-row"><span><b>單字家族顏色提示</b><small>高階抽象主題一律移除顏色提示。</small></span><input type="checkbox" id="color-setting" ${data.settings.color?'checked':''}></label><label class="settings-row"><span><b>每天練習時間</b><small>達到時間後暫停單人遊戲；設定僅保留在此裝置。</small></span><select id="time-limit">${[15,20,30,45,60].map(n=>`<option value="${n}" ${data.settings.limit===n?'selected':''}>${n} 分鐘</option>`).join('')}</select></label><div class="settings-row"><span><b>公開排行榜</b><small>本版只提供當前伺服器的對戰紀錄，不發布個人資料。</small></span><span class="pill">預設保護隱私</span></div><div class="settings-row"><span><b>資料保留位置</b><small>單人紀錄存於此瀏覽器；清除網站資料會移除進度。</small></span><button class="text-btn" id="backup">匯出備份 ↓</button></div><div class="settings-row"><span><b>還原自己的備份</b><small>只接受此作品匯出的 JSON 紀錄。</small></span><label class="text-btn" style="cursor:pointer">選擇檔案<input type="file" accept=".json,application/json" id="restore" hidden></label></div><div class="settings-row"><span><b>重新開始</b><small>清除此裝置的全部冒險紀錄。</small></span><button class="text-btn" id="reset" style="color:#b47f68">重設紀錄</button></div></div><div class="study-tip" style="max-width:700px;margin-top:20px"><b>🌿 讓學習的快樂留久一點</b>不販售過關道具、不顯示廣告，也不限制體力。這個版本的每日時長屬於裝置提醒與阻擋，尚未提供經家長驗證、不可由孩子修改的帳號控制。</div>`);$('#sound-setting').onchange=e=>{data.settings.sound=e.target.checked;save()};$('#accent').onchange=e=>{data.settings.accent=e.target.value;save();speak('Hello, little explorer')};$('#color-setting').onchange=e=>{data.settings.color=e.target.checked;save()};$('#time-limit').onchange=e=>{data.settings.limit=+e.target.value;save()};$('#backup').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='word-pop-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#restore').onchange=restore;$('#reset').onclick=()=>{modal('<h2>確定重新開始？</h2><p>此裝置的關卡、單字與測驗紀錄都會清除。建議先匯出備份。</p><button class="btn peach" id="confirm-reset">清除並重新開始</button><button class="btn secondary" id="cancel-reset">保留紀錄</button>');$('#confirm-reset').onclick=()=>{data=defaults();save();closeModal();show('home')};$('#cancel-reset').onclick=closeModal}}
async function restore(e){try{const file=e.target.files[0];if(!file||file.size>500000)throw Error('備份檔太大');const x=validateSave(JSON.parse(await file.text()));if(x.version!==1||!Number.isInteger(x.unlocked)||x.unlocked<1||x.unlocked>80||!Array.isArray(x.history)||!x.review||typeof x.review!=='object'||!x.quiz||typeof x.quiz!=='object'||!x.stars||typeof x.stars!=='object'||!Number.isFinite(x.coins)||x.coins<0)throw Error('備份格式不正確');modal('<h2>還原冒險紀錄？</h2><p>這會取代目前裝置上的進度與單字本。</p><button class="btn" id="confirm-restore">還原備份</button><button class="btn secondary" id="cancel-restore">取消</button>');$('#confirm-restore').onclick=()=>{data={...defaults(),...x,settings:{...defaults().settings,...x.settings}};save();closeModal();show('home');toast('冒險紀錄已還原。')};$('#cancel-restore').onclick=closeModal}catch(err){toast('無法讀取備份：'+err.message)}}
function modal(html,onClose=null,closable=true){modalReturn=document.activeElement;closeModal(false);$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="冒險視窗">${closable?'<button class="icon close" id="modal-close" aria-label="關閉">×</button>':''}${html}</section></div>`;const title=$('.modal h2');if(title){title.id='dialog-title';$('.modal').setAttribute('aria-labelledby','dialog-title')}$('#app').inert=true;modal.onClose=onClose;modal.closable=closable;if($('#modal-close'))$('#modal-close').onclick=closeModal;const first=$('.modal button, .modal input');first?.focus({preventScroll:true});bindCommon()}
function closeModal(run=true){$('#modal-root').innerHTML='';$('#app').inert=false;if(run){modal.onClose?.();modalReturn?.isConnected&&modalReturn.focus({preventScroll:true})}modal.onClose=null}
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape'&&modal.closable){e.preventDefault();closeModal()}if(e.key==='Tab'){const items=[...document.querySelectorAll('.modal button:not(:disabled),.modal input,.modal select')];if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function help(){modal(`<div class="eyebrow">HELLO, LITTLE EXPLORER</div><h2>讓同一個單字，連成一線。</h2><div class="example"><b>🐱</b><b>cat</b><b>貓</b></div><div class="help-step"><span>1</span><div>點選兩格，或向旁邊滑動，交換相鄰方塊。</div></div><div class="help-step"><span>2</span><div>同一家族橫向或直向連成 3 格就消除，圖、英文、中文可以混搭。</div></div><div class="help-step"><span>3</span><div>完成目標就過關。無效交換不扣步數；沒有合法交換時會自動重排。</div></div><p>4 連產生閃電、5 連產生彩虹；兩條 3 連交叉成 L / T（至少 5 格）產生炸彈。幸運星觸發後會自動進行 3 次合法配對。</p><p>鍵盤：方向鍵移動焦點，Enter 選取；Shift＋方向鍵交換。配對紀錄只反映遊戲操作，單字是否學會請用小測驗確認。</p><button class="btn" id="got-it">明白了，出發！ →</button>`);$('#got-it').onclick=closeModal}
async function api(path,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),6000);try{const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:controller.signal});const value=await r.json();if(!r.ok)throw Error(value.error||value.message||'連線失敗');return value}catch(e){if(e.name==='AbortError')throw Error('連線逾時，請稍後重試。');throw e}finally{clearTimeout(timer)}}
function isLocalInvite(){return ['localhost','127.0.0.1','[::1]'].includes(location.hostname)}
function inviteUrl(id){const url=new URL('./',location.href);url.searchParams.set('view','multi');url.searchParams.set('room',id);return url.href}
function roomIdFromInput(value){let id=value.trim();if(!/^[a-f0-9]{48}$/i.test(id)){let url;try{url=new URL(id)}catch{throw Error('請貼上完整邀請連結或房間代碼。')}if(url.origin!==location.origin)throw Error('這個邀請來自另一個服務網址，請直接開啟朋友的完整連結。');id=url.searchParams.get('room')||''}if(!/^[a-f0-9]{48}$/i.test(id))throw Error('房間代碼格式不正確，請再向朋友確認。');return id.toLowerCase()}
async function multi(){shell(`${heading('BETTER TOGETHER','好朋友，來場小挑戰。','相同起始棋盤，兩分鐘友善競賽。或組隊一起達成目標。',`<button class="btn small secondary" data-go="ranks">排行榜 ↗</button>`)}<div id="multi-content"><div class="empty"><div class="load-tiles" style="justify-content:center"><span>🤝</span><span>⚡</span><span>⭐</span></div><p>正在尋找冒險夥伴的房間⋯⋯</p></div></div>`);try{const r=await api('rooms');apiOnline=true;if(page!=='multi')return;$('#multi-content').innerHTML=`<div class="daily-strip" style="margin:0 0 23px"><span class="daily-icon">🌐</span><div><b>即時房間已連線</b><p>建立房間後複製邀請連結給朋友，或輸入朋友提供的房間代碼。</p></div><button class="btn small" id="create-room" style="margin-left:auto">＋ 建立房間</button></div><form id="join-by-code" class="room-invite"><label class="form-label" for="join-code">有朋友的邀請嗎？</label><div class="invite-row"><input class="field" id="join-code" maxlength="2048" placeholder="貼上邀請連結或房間代碼" required><button class="btn small secondary" type="submit">加入朋友</button></div><p id="join-code-error" class="error" role="alert"></p></form><div class="section-head"><h2>等待出發的房間</h2><button class="text-btn" id="refresh-rooms">重新整理 ↻</button></div>${r.rooms.length?`<div class="room-grid">${r.rooms.map(room=>`<article class="room-card"><span style="font-size:35px">${room.mode==='duel'?'⚔️':'🤝'}</span><h3>${esc(room.name)} ${room.hasPassword?'🔒':''}</h3><p>${room.mode==='duel'?'1v1 友善對戰':'2–4 人組隊合作'} · ${room.count} / ${room.capacity} 位夥伴</p><button class="btn secondary" data-join="${room.id}" ${room.count>=room.capacity?'disabled':''}>加入挑戰 →</button></article>`).join('')}</div>`:'<div class="empty"><div class="empty-icon">🏕️</div><h3>第一個房間，等你來開張。</h3><p>邀請一位朋友，同一個起點，不同的冒險。</p><button class="btn" id="create-first-room">建立房間 →</button></div>'}<p class="footer-note">等待房間有效兩小時 · 對戰使用裝置回報分數</p>`;$('#create-room').onclick=()=>roomForm();if($('#create-first-room'))$('#create-first-room').onclick=()=>roomForm();$('#refresh-rooms').onclick=multi;$('#join-by-code').onsubmit=e=>{e.preventDefault();try{roomForm(roomIdFromInput($('#join-code').value))}catch(error){$('#join-code-error').textContent=error.message}};document.querySelectorAll('[data-join]').forEach(b=>b.onclick=()=>roomForm(b.dataset.join));bindCommon();if(multi.invite){const id=multi.invite;multi.invite=null;roomForm(id)}}catch(e){apiOnline=false;if(page!=='multi')return;$('#multi-content').innerHTML=`<div class="empty"><div class="empty-icon">🏕️</div><h3>這裡還沒有連上房間伺服器。</h3><p>目前頁面可以完整體驗單人冒險。<br>多人模式需要啟動作品附帶的房間伺服器，再從它的網址進入。<br>連線後就能建立真正的雙人對戰與組隊房間。</p><button class="btn" id="retry-server">重新檢查連線</button><button class="btn secondary" data-go="map" style="margin-left:12px">先去單人冒險 →</button></div>`;$('#retry-server').onclick=multi;bindCommon()}}
function roomForm(id=null){modal(`<div class="modal-hero">${id?'🤝':'🏕️'}</div><h2>${id?'加入朋友的冒險':'開一個單字小營地'}</h2><label class="form-label" for="nickname">你的暱稱（不用真實姓名）</label><input class="field" id="nickname" maxlength="20" placeholder="例如：小狐狸">${id?'':`<label class="form-label" for="room-name">房間名稱</label><input class="field" id="room-name" maxlength="30" placeholder="放學後的單字冒險"><label class="form-label" for="room-mode">挑戰方式</label><select class="field" id="room-mode"><option value="duel">⚔ 1v1 友善對戰</option><option value="team">🤝 2–4 人組隊挑戰</option></select>`}<label class="form-label" for="room-password">${id?'房間密碼（如果有設定）':'房間密碼（選填）'}</label><input class="field" type="password" id="room-password" maxlength="64"><p class="error" id="room-error" role="alert"></p><button class="btn" id="room-submit">${id?'加入房間':'建立房間'} →</button>`);$('#room-submit').onclick=async()=>{const b=$('#room-submit');b.disabled=true;const nickname=$('#nickname').value.trim();if(!nickname){$('#room-error').textContent='先為自己取一個暱稱吧。';b.disabled=false;return}try{const r=await api(id?`rooms/${id}/join`:'rooms',{nickname,password:$('#room-password').value,...(!id?{name:$('#room-name').value,mode:$('#room-mode').value}:{})});roomSession={...r};closeModal();lobby();pollRoom()}catch(e){$('#room-error').textContent=e.message;b.disabled=false}}}
function lobby(){page='multi';const r=roomSession.room;shell(`${heading('YOUR LITTLE CAMPSITE',esc(r.name),'等夥伴到齊，房主就可以帶大家出發。')}<div class="panel" style="max-width:680px;margin:auto"><div class="eyebrow">${r.mode==='duel'?'FRIENDLY DUEL':'TEAM ADVENTURE'} · ${r.members.length} / ${r.capacity}</div><h3>${r.mode==='duel'?'兩分鐘，找到更多好朋友。':'一起消除 120 格單字方塊。'}</h3><p>共同起始棋盤 · 動物園單字 · 無道具加成</p><section class="room-invite" aria-label="邀請朋友"><label class="form-label" for="invite-link">把這個連結傳給朋友</label><div class="invite-row"><input class="field" id="invite-link" readonly value="${esc(inviteUrl(r.id))}"><button class="btn small secondary" id="copy-invite">複製邀請連結</button></div><details><summary>使用房間代碼加入</summary><p class="room-code">${esc(r.id)}</p><p>朋友到「同行對戰」貼上此代碼，再填暱稱與房間密碼（若有設定）。</p></details><p class="invite-note">${isLocalInvite()?'目前是本機網址，只能在這台電腦開啟；另一台裝置需使用可連線的同一伺服器網址。':'朋友開啟連結後填寫暱稱即可加入；若設有密碼，請另外告訴朋友。'}</p><p id="invite-status" role="status" aria-live="polite"></p></section><div id="lobby-members">${membersHTML(r)}</div><p class="error" id="lobby-error" role="alert"></p>${r.hostId===roomSession.memberId?`<button class="btn" id="start-room" ${r.members.length<2?'disabled':''}>大家都到了，開始挑戰 →</button>`:'<p>等待房主開始⋯⋯</p>'}<button class="btn secondary" id="leave-room">離開房間</button><p style="font-size:10px;margin-top:20px">邀請連結只包含房間代碼，不包含你的登入或房主憑證。房間開始、額滿或到期後，朋友將無法加入。</p></div>`);$('#copy-invite').onclick=async()=>{const link=$('#invite-link'),status=$('#invite-status');try{await navigator.clipboard.writeText(link.value);if(status.isConnected)status.textContent='邀請連結已複製，貼到你和朋友的聊天中即可。'}catch{if(link.isConnected){link.focus();link.select();status.textContent='請複製上方已選取的邀請連結。'}}};if($('#start-room'))$('#start-room').onclick=async()=>{try{roomSession.room=await api(`rooms/${r.id}/start`,{token:roomSession.token});await launchOnline()}catch(e){$('#lobby-error').textContent=e.message}};$('#leave-room').onclick=async()=>{await leaveSession();show('multi')}}
function membersHTML(r){return r.members.map((m,i)=>`<div class="member"><span><i>${['🦊','🐨','🐼','🐰'][i]}</i> ${esc(m.nickname)}${m.id===roomSession.memberId?'（你）':''}</span><b>${r.status==='waiting'?(m.id===r.hostId?'房主':'已準備'):m.score+' 分'}</b></div>`).join('')}
let polling=false,launching=false;
function pollRoom(){clearInterval(roomTimer);roomTimer=setInterval(async()=>{if(!roomSession||polling)return;polling=true;try{const old=roomSession.room;const r=await api(`rooms/${old.id}/state?token=${encodeURIComponent(roomSession.token)}`);if(!roomSession||roomSession.room.id!==old.id)return;roomSession.room=r;if(r.status==='playing'&&page==='multi'&&!launching)await launchOnline();else if(r.status==='waiting'&&page==='multi'&&$('#lobby-members')){if(r.hostId!==old.hostId){lobby();return;}$('#lobby-members').innerHTML=membersHTML(r);if($('#start-room'))$('#start-room').disabled=r.members.length<2}else if(r.status==='finished'&&page==='game'&&game?.online&&!busy){onlineResult(r)}if(page==='game'&&game?.online){$('#moves')&&($('#moves').textContent=onlineSeconds());if($('#opponents'))$('#opponents').innerHTML=r.members.map(m=>`<div class="stat-row"><span>${esc(m.nickname)}${m.id===roomSession.memberId?' · 你':''}</span><b>${m.score}</b></div>`).join('')+(r.mode==='team'?`<p>團隊進度 ${r.members.reduce((a,m)=>a+m.cleared,0)} / 120</p>`:'')}}catch(e){if(page==='game'&&$('#opponents'))$('#opponents').textContent='連線中斷，正在重新同步⋯⋯';else if($('#lobby-error'))$('#lobby-error').textContent=e.message}finally{polling=false}},1000)}
async function launchOnline(){if(launching)return;launching=true;await startLevel(1,{online:true,seed:roomSession.room.seed,audio:true});launching=false}
function onlineSeconds(){if(!roomSession?.room.startedAt)return 120;return Math.max(0,Math.ceil(roomSession.room.duration-(Date.now()-roomSession.room.startedAt)/1000))}
async function submitScore(done){if(!game?.online||!roomSession||game.onlineDone)return;try{const r=await api(`rooms/${roomSession.room.id}/score`,{token:roomSession.token,score:game.score,cleared:game.cleared,done});roomSession.room=r;if(done)game.onlineDone=true;if(r.status==='finished'&&!busy)onlineResult(r)}catch(e){toast('分數尚未同步：'+e.message)}}
function onlineResult(r){if(!game||!game.online||game.ended||!roomSession)return;clearInterval(roomTimer);game.ended=true;record(r.mode==='team'?r.winner==='team':r.winner===roomSession.memberId);const me=r.members.find(m=>m.id===roomSession.memberId);const won=r.mode==='team'?r.winner==='team':r.winner===roomSession.memberId;modal(`<div class="result"><div class="modal-hero">${won?'🎉':'🤝'}</div><div class="eyebrow">BETTER TOGETHER</div><h2>${won?'一起進步，就是最棒的事！':r.winner==='tie'?'默契滿分，這場平手！':'謝謝你，一起完成這場冒險。'}</h2><p>${r.mode==='team'?`團隊總共消除了 ${r.members.reduce((a,m)=>a+m.cleared,0)} / 120 格。`:'每次挑戰，都是和單字再見一次面。'}</p>${r.members.sort((a,b)=>b.score-a.score).map(m=>`<div class="stat-row"><span>${esc(m.nickname)}${m.id===me?.id?' · 你':''}</span><b>${m.score} 分</b></div>`).join('')}<button class="btn" id="online-back">回到好友挑戰 →</button><button class="btn secondary" id="online-rank">看看本次伺服器排行榜</button></div>`,null,false);$('#online-back').onclick=()=>{closeModal();roomSession=null;show('multi')};$('#online-rank').onclick=()=>{closeModal();roomSession=null;show('ranks')};if(won)confetti()}
async function ranks(scope='all'){
 shell(`${heading('CELEBRATE EVERY EXPLORER','每一次努力，都值得鼓掌。','登入自己的 ID，保存每關最佳紀錄。排行榜只顯示選擇公開的遊戲暱稱。',`<button class="btn small secondary" data-go="account">${currentUser()?'我的冒險 ID':'建立 ID / 登入'} →</button>`)}<div class="tabs"><button data-rank-scope="all" class="${scope==='all'?'active':''}">全服總榜</button><button data-rank-scope="week" class="${scope==='week'?'active':''}">本週主題榜</button><button data-rank-scope="grade" class="${scope==='grade'?'active':''}">同年級分組</button><button id="personal-rank">我的個人進步</button></div><div class="panel" id="rank-content"><p>正在載入真實遊玩紀錄⋯⋯</p></div>`);
 $('#personal-rank').onclick=()=>show('report');document.querySelectorAll('[data-rank-scope]').forEach(b=>b.onclick=()=>ranks(b.dataset.rankScope));
 try{const r=await api('leaderboard?scope='+encodeURIComponent(scope));if(page!=='ranks')return;
 $('#rank-content').innerHTML=r.entries.length?`<div class="table-wrap"><table><thead><tr><th>名次</th><th>探險家暱稱</th><th>年級分組</th><th>最佳紀錄積分</th></tr></thead><tbody>${r.entries.slice(0,50).map((x,i)=>`<tr><td>${i<3?['🥇','🥈','🥉'][i]:i+1}</td><td>${esc(x.nickname)}</td><td>${esc(({lower:'國小低年級',upper:'國小高年級',junior:'國中'})[x.grade]||'尚未分組')}</td><td>${x.score}</td></tr>`).join('')}</tbody></table></div><p style="font-size:10px">${esc(r.notice||'相同關卡只計最佳成績。分數由遊戲裝置回報，尚未用於正式獎勵競賽。')}</p>`:'<div class="empty"><span class="empty-icon">🏆</span><h3>下一場精彩，等你來寫。</h3><p>登入 ID、開啟暱稱公開，再完成一關就能留下排行榜紀錄。<br>自由體驗與訪客模式不計入。</p><button class="btn" data-go="account">前往我的冒險 ID →</button></div>';bindCommon();
 }catch(error){if(page!=='ranks')return;$('#rank-content').innerHTML=`<div class="empty"><span class="empty-icon">🌐</span><h3>排行榜暫時還沒連上。</h3><p>${esc(error.message)}<br>你的本機遊玩紀錄仍然保留。</p><button class="btn" id="rank-retry">重新載入</button></div>`;$('#rank-retry').onclick=()=>ranks(scope)}
}

setInterval(()=>{const today=new Date().toLocaleDateString('en-CA');if(data.day!==today){data.day=today;data.seconds=0;save()}if(qaRunning||page!=='game'||!game||game.ended||game.paused||document.hidden)return;game.activeSeconds++;data.seconds++;if(game.online){if(onlineSeconds()<=0&&!busy)submitScore(true)}else if(data.seconds>=data.settings.limit*60&&!busy){game.paused=true;record(false);game.ended=true;save();modal(`<div class="modal-hero">🌿</div><h2>今天也很努力了，休息一下吧。</h2><p>已達到今天 ${data.settings.limit} 分鐘的練習時間。<br>站起來走走，讓眼睛看看遠方。</p><button class="btn" id="time-rest">回到冒險基地</button>`,null,false);$('#time-rest').onclick=()=>{closeModal();show('home')}}if(data.seconds%10===0)save()},1000);
window.addEventListener('beforeunload',()=>save());
const entryParams=new URLSearchParams(location.search);if(entryParams.has('room')){try{multi.invite=roomIdFromInput(entryParams.get('room'));show('multi')}catch{show('multi');toast('邀請代碼格式不正確，請向朋友確認。')}}else if(['map','multi','review','report','ranks'].includes(entryParams.get('view')))show(entryParams.get('view'));else home();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

async function leaveSession(){const session=roomSession;roomSession=null;clearInterval(roomTimer);if(!session)return;try{await api(`rooms/${session.room.id}/leave`,{token:session.token})}catch{toast('已離開畫面；伺服器房間將自動到期。')}}

if(document.fonts){const refitFonts=()=>{fitCache.clear();const board=$('#board');if(board){const width=(board.clientWidth-18-(SIZE-1)*6)/SIZE;for(const el of board.children)fitLabel(el,width)}};document.fonts.ready.then(refitFonts);document.fonts.addEventListener?.('loadingdone',refitFonts)}

configureAccounts({shell,toast,getSave:()=>qaBackup||data,setSave:value=>{if(qaRunning){qaBackup=value?validateSave(value):defaults();return}data=value?validateSave(value):defaults();const today=new Date().toLocaleDateString('en-CA');if(data.day!==today){data.day=today;data.seconds=0}save();},navigate:show,changed:()=>{if(page==='home')home();else if(page==='account')accountPage()}});

function qualityLab(){page='qa';shell(`${heading('ACTUAL BROWSER REPLAY · NOT A HUMAN STUDY','80 關，逐關走一次。','在暫存測試進度中，使用已驗證的合法交換重播；不改寫玩家存檔、不上傳排行榜。')}<div class="panel"><h3>完整流程與動畫回放</h3><p>每關依序開啟預覽、載入棋盤、進行合法交換、顯示勝利與回到解鎖地圖。檢查相同棋盤節點與掉落存活方塊節點持續存在。這是瀏覽器自動測試，不冒稱 80 關真人試玩。</p><label class="settings-row"><span><b>快速檢查</b><small>關閉後使用正常動畫時間；開啟後驗證狀態與節點。</small></span><input id="qa-fast" type="checkbox"></label><button class="btn" id="qa-start">執行全部 80 關 →</button><div id="qa-results" role="status" aria-live="polite"></div></div>`);$('#qa-start').onclick=()=>runQualityLab($('#qa-fast').checked)}
async function runQualityLab(fast=false){
 if(qaRunning)return;qaRunning=true;qaAbort=false;qaFast=fast;runQualityLab.inputs=null;qaBackup=structuredClone(data);const priorSound=data.settings.sound;data=defaults();data.settings.sound=false;const results=[];let overlay;
 try{const res=await fetch('./qa-cases.json',{cache:'no-store'});if(!res.ok)throw Error('尚未載入逐關測試案例');const cases=await res.json();if(!Array.isArray(cases.levels)||cases.levels.length!==80||cases.levels.some((c,i)=>c.level!==i+1||!c.expected||!Array.isArray(c.moves)))throw Error('測試案例必須完整包含依序 1–80 關');runQualityLab.inputs=cases.inputs;overlay=document.createElement('aside');overlay.id='qa-overlay';overlay.innerHTML='<b>80 關瀏覽器驗收中</b><p id="qa-status"></p><button id="qa-stop">停止測試並還原</button>';document.body.append(overlay);$('#qa-stop').onclick=()=>qaAbort=true;
 for(const testCase of cases.levels){if(qaAbort)throw Error('已由操作人停止');const row={level:testCase.level,passed:false,checks:[],score:0};results.push(row);$('#qa-status').textContent=`第 ${testCase.level} / 80 關 · ${themes[Math.floor((testCase.level-1)/4)].name}`;
 page='map';themeIndex=Math.floor((testCase.level-1)/4);map();preview(testCase.level);if(!$('#start-level'))throw Error('關卡預覽入口遺失：'+testCase.level);row.checks.push('預覽');closeModal();await startLevel(testCase.level,{seed:testCase.seed});if(game.size&&game.size!==testCase.expected.size)throw Error('棋盤尺寸不符');if(SIZE!==testCase.expected.size)throw Error('主題棋盤尺寸不符');row.checks.push('載入與棋盤');
 for(const [a,b]of testCase.moves){if(qaAbort)throw Error('已由操作人停止');if(game.moves===0){if(!testCase.extended||!$('#extra-moves'))throw Error('非預期耗盡步數');$('#extra-moves').onclick();row.checks.push('免費加步僅一次')}
 const board=$('#board'),nodes=new Map([...board.children].map(el=>[el.dataset.uid,el])),oldMoves=game.moves;await move(a,b);if($('#board')!==board)throw Error('消除替換了整個棋盤');if(game.moves!==oldMoves-1)throw Error('合法交換未正確扣步');for(const el of board.children)if(nodes.has(el.dataset.uid)&&nodes.get(el.dataset.uid)!==el)throw Error('存活方塊節點被重建');
 }
 if(!game.ended||!$('#back-map'))throw Error('未到達實際勝利視窗');if(game.score!==testCase.expected.score||game.progress!==testCase.expected.progress||game.obstacles!==testCase.expected.obstacles)throw Error('勝利數值與重播不符');row.checks.push('交換、消除、補落與節點連續','勝利視窗與數值');row.score=game.score;$('#back-map').onclick();if(data.unlocked!==Math.min(80,testCase.level+1))throw Error('下一關未解鎖');row.checks.push('返回地圖與下一關');row.passed=true;await sleep(80);
 }
 }catch(error){results.push({error:error.message,passed:false})}finally{if(game)game.ended=true;busy=false;selected=-1;closeModal();data=qaBackup;qaBackup=null;qaRunning=false;qaFast=false;overlay?.remove();page='qa';qualityLab();const passed=results.filter(r=>r.passed).length,failed=results.some(r=>r.error)||passed!==80;const evidence={at:new Date().toISOString(),inputs:runQualityLab.inputs,reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,method:fast?'瀏覽器快速狀態與 DOM 回放':'瀏覽器正常動畫回放',passed,total:80,results};window.wordPopQA=evidence;$('#qa-results').innerHTML=`<h3>${failed?'尚未通過':'全部通過'}：${passed} / 80 關</h3><p>${esc(results.find(r=>r.error)?.error||'80 關皆到達實際勝利視窗、返回地圖並正確解鎖。玩家原始進度已還原。')}</p><div class="table-wrap"><table><thead><tr><th>關卡</th><th>結果</th><th>分數</th></tr></thead><tbody>${results.filter(r=>r.level).map(r=>`<tr><td>${r.level}</td><td>${r.passed?'通過':'失敗'}</td><td>${r.score}</td></tr>`).join('')}</tbody></table></div><button class="btn secondary" id="qa-download">下載本次瀏覽器驗收紀錄</button>`;$('#qa-download').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(evidence,null,2)],{type:'application/json'}));a.download='wordpop-browser-80levels.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}
}

function chooseCharacter(){modal(`<div class="eyebrow">YOUR LITTLE TRAVEL COMPANION</div><h2>誰陪你一起出發？</h2><p>每位夥伴都一樣勇敢。選你喜歡的，就好。</p><div class="character-options">${characters.map(c=>`<button class="character-choice ${characterId===c.id?'chosen':''}" data-character="${c.id}" aria-pressed="${characterId===c.id}"><span style="background:${c.color}">${c.icon}</span><b>${c.name}</b><small>${c.note}</small>${characterId===c.id?'<i>✓ 已選擇</i>':'<i>選這位夥伴</i>'}</button>`).join('')}</div><button class="btn" id="character-done">一起去冒險 →</button>`);document.querySelectorAll('[data-character]').forEach(b=>b.onclick=()=>{characterId=b.dataset.character;try{localStorage.setItem('wordpop-character',characterId)}catch{}sound();chooseCharacter()});$('#character-done').onclick=()=>{closeModal();map()}}
async function walkOnMap(destination,unlocked=false){const walker=$('#map-walker'),world=$('.map-world'),svg=$('.map-path'),path=$('#trail-route');if(!walker||!world||!svg||!path)return;const points=[[24,380],[49,295],[70,215],[51,140]],to=Math.max(0,Math.min(3,destination));const start=unlocked?Math.max(0,to-1):Number(walker.dataset.position??Math.min(3,Math.max(0,data.unlocked-themeIndex*4-1)));walker.dataset.position=to;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced){walker.style.left=points[to][0]+'%';walker.style.top=points[to][1]-57+'px';return}
 const total=path.getTotalLength(),wr=world.getBoundingClientRect(),sr=svg.getBoundingClientRect(),scaleX=sr.width/600,scaleY=sr.height/440;
 function nearest(index){const target={x:points[index][0]/100*wr.width,y:points[index][1]};let best=0,distance=Infinity;for(let i=0;i<=240;i++){const len=total*i/240,p=path.getPointAtLength(len),x=p.x*scaleX+sr.left-wr.left,y=p.y*scaleY+sr.top-wr.top,d=(x-target.x)**2+(y-target.y)**2;if(d<distance){distance=d;best=len}}return best}
 const fromLength=nearest(start),toLength=nearest(to),frames=[];for(let i=0;i<=40;i++){const p=path.getPointAtLength(fromLength+(toLength-fromLength)*i/40);frames.push({left:p.x*scaleX+sr.left-wr.left+'px',top:p.y*scaleY+sr.top-wr.top-57+'px'})}
 walker.classList.add('walking');if(unlocked)toast(`${character().name}帶你前往第 ${themeIndex*4+to+1} 關！`);const motion=walker.animate(frames,{duration:start===to?300:1100,easing:'cubic-bezier(.25,.65,.3,1)',fill:'forwards'});try{await motion.finished}catch{}if(!world.isConnected){motion.cancel();return}walker.style.left=points[to][0]+'%';walker.style.top=points[to][1]-57+'px';motion.cancel();walker.classList.remove('walking');if(unlocked){const node=$(`[data-level="${themeIndex*4+to+1}"]`);node?.classList.add('arrived');setTimeout(()=>node?.classList.remove('arrived'),1000)}}
